import hashlib,json,pathlib,runpy,sys
if not __debug__:raise RuntimeError('Canary admission requires unoptimized Python')
unit=pathlib.Path(sys.argv[2]);out=pathlib.Path(sys.argv[1])
expected='a251c7003e5e40d746e70c069adbd2f0430c32e90dc6a0220f17ad98daa69a0f'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
if sha(unit/'unit-validation.json')!=expected:raise ValueError('Pinned unit artifact differs')
sys.argv=['experiments/q_rmea_protected_context_train.py','canary','--output',str(out),'--unit-output',str(unit)]
runpy.run_path(sys.argv[0],run_name='__main__')
import torch
from baselines.retacred import rmea_protected_context_protocol as p
from baselines.retacred.rmea_token_transport_parallel import equal_state
seal=p.read(out/'RUN_COMPLETE');validation=out/'canary-validation.json'
if seal['artifacts']['canary-validation.json']!=sha(validation) or p.read(validation).get('gate') is not True:raise ValueError('Primary canary seal differs')
suffix=out.parent.name
roots=[out/('serial-'+suffix)/'discovery',out/('canary-'+suffix)/'discovery',out/'restored'/('canary-'+suffix)/'discovery']
checks={}
for kind in p.MODES:
 states=[torch.load(root/'.workers'/kind/'latest.pt',map_location='cpu',weights_only=True) for root in roots]
 if any(set(s.get('rng',{}))!={'python','numpy','torch','cuda'} for s in states):raise ValueError('Incomplete persisted RNG')
 if not all(equal_state(states[0]['rng'],s['rng']) for s in states[1:]):raise ValueError('Serial/local/COS RNG continuation differs: '+kind)
 checks[kind]=dict(python=True,numpy=True,torch=True,cuda=True,lanes=3)
p.atomic_json(out/'canary-acceptance.json',dict(schema='q-rmea.protected-context.canary-acceptance.v1',gate=True,unit_sha256=expected,primary_validation_sha256=sha(validation),primary_seal_sha256=sha(out/'RUN_COMPLETE'),rng=checks,source_sha256=p.identity(p.sources()),contract_sha256=p.identity(p.contract()),scope='Owner wrapper verifies exact accepted unit before official CLI, then all persisted RNG across3 completed lanes. No mutation of primary seal or scientific source; no full training admission.'))
print(json.dumps(dict(canary_acceptance=True,rng_conditions=len(checks),unit_pin=True)))
